'use client';
import {useState} from 'react';
import type {RecordRow as R} from '@/lib/erp-primitives';
import {day} from '@/lib/erp-primitives';
import type {Access} from '@/lib/access-policy';
import {canAssignCRM,crmProfile} from '@/lib/access-policy';
type Act=(input:Record<string,unknown>)=>Promise<{id?:string}|false|undefined>;
export default function DealEvidence({deal,records,act,busy,access}:{deal:R;records:R[];act:Act;busy:boolean;access?:Access}){
 const [adding,setAdding]=useState(false),[error,setError]=useState('');
 const docs=records.filter(r=>r.type==='document'&&r.crmEvidence===true&&r.dealId===deal.id&&r.company===deal.company),canVerify=!!access&&canAssignCRM(access),canCreate=!access||crmProfile(access)!=='field_ops';
 return <section className="crm-detail-section"><h3>Deal evidence</h3><p>Verification applies to this deal and this document version. Returning a document to Draft invalidates its approval.</p>{docs.map(doc=><article className="crm-target-row" key={doc.id}><strong>{doc.name}</strong><p>{doc.documentKind} · Revision {doc.revisionLabel} · {doc.status} · Review due {doc.reviewDue||'Not recorded'}</p>{doc.sourceUrl&&<a href={doc.sourceUrl} target="_blank" rel="noreferrer">Open source document</a>}<div className="sectiontoolbar">{doc.status==='Draft'&&canCreate&&<button type="button" className="secondary" disabled={busy} onClick={()=>void act({action:'stage',id:doc.id,expectedVersion:doc.version,status:'Review'})}>Submit for review</button>}{doc.status==='Review'&&canVerify&&<button type="button" className="secondary" disabled={busy} onClick={()=>{if(window.confirm('Confirm you reviewed the actual source and approve this document for this deal.'))void act({action:'stage',id:doc.id,expectedVersion:doc.version,status:'Verified'});}}>Verify document</button>}{doc.status==='Verified'&&canVerify&&<button type="button" className="secondary" disabled={busy} onClick={()=>void act({action:'stage',id:doc.id,expectedVersion:doc.version,status:'Draft'})}>Revoke verification</button>}</div></article>)}{canCreate&&<button type="button" className="secondary" disabled={busy} onClick={()=>setAdding(v=>!v)}>{adding?'Cancel document':'Register deal document'}</button>}{adding&&<form className="crm-evidence-form" onSubmit={async event=>{event.preventDefault();setError('');const data=Object.fromEntries(new FormData(event.currentTarget));const result=await act({...data,action:'create',type:'document',crmEvidence:true,dealId:deal.id,company:deal.company,classification:'Verified Evidence',date:day()});if(result&&result.id)setAdding(false);else setError('Document not saved. Review the workspace message.');}}><label>Document name<input required name="name" maxLength={500}/></label><label>Document kind<select name="documentKind"><option>Hydrogeological survey</option><option>Site assessment</option><option>Contract</option><option>Customer testimonial</option></select></label><label>Source document HTTPS link<input required name="sourceUrl" type="url" pattern="https://.*" maxLength={2000}/></label><label>Source reference<input required name="sourceRef" maxLength={500}/></label><label>Revision<input required name="revisionLabel" maxLength={100}/></label><label>Record owner<input required name="owner" defaultValue={access?.email||deal.owner} maxLength={500}/></label><label>Next review date<input required name="reviewDue" type="date"/></label>{error&&<p role="alert">{error}</p>}<button disabled={busy} className="primary">Save document draft</button></form>}</section>;
}
